// checkTokenPublicOnly(): tokens restricted to public-only may not access private resources.

// reqToken(): authentication only — the request must be signed in with a token (401 otherwise). No authorization.

func reqAnyRepoReader() func(ctx *context.APIContext) {
	return func(ctx *context.APIContext) {
		if !ctx.Repo.Permission.HasAnyUnitAccess() && !ctx.IsUserSiteAdmin() {
			ctx.APIError(http.StatusForbidden, "user should have any permission to read repository or permissions of site admin")
			return
		}
	}
}

// ---- handler repo.ListCollaborators (routers/api/v1/repo/collaborators.go:27-74)
func ListCollaborators(ctx *context.APIContext) {

	collaborators, total, err := repo_model.GetCollaborators(ctx, &repo_model.FindCollaborationOptions{
		ListOptions: utils.GetListOptions(ctx),
		RepoID:      ctx.Repo.Repository.ID,
	})
	if err != nil {
		ctx.APIErrorInternal(err)
		return
	}

	users := make([]*api.User, len(collaborators))
	for i, collaborator := range collaborators {
		users[i] = convert.ToUser(ctx, collaborator.User, ctx.Doer)
	}

	ctx.SetTotalCountHeader(total)
	ctx.JSON(http.StatusOK, users)
}

